import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 collectAmt, uint256 msgValue) public {
        // Bound values to avoid overflows in internal safe math
        minSum = bound(minSum, 1, type(uint256).max / 2);
        lockTime = bound(lockTime, 1, type(uint256).max / 2);
        collectAmt = bound(collectAmt, 1, minSum);
        msgValue = bound(msgValue, collectAmt, type(uint256).max / 2);

        // Deploy an adversarial callee that always reverts to trigger the Collect failure path
        // The bug changes MinSum so we need a Collect call that returns false (failing transfer) but doesn't revert the whole tx
        Reverter reverter = new Reverter();
        address user = address(reverter);

        // Setup: set MinSum before initialization
        c.SetMinSum(minSum);
        c.SetLogFile(address(0x1));
        c.Initialized();

        // Fund the user and call Put to set balance and unlockTime
        vm.deal(user, msgValue);
        vm.prank(user);
        c.Put{value: msgValue}(lockTime);

        // Warp past unlockTime so the time condition is satisfied
        vm.warp(block.timestamp + lockTime + 1);

        // Call Collect: the low-level call to the Reverter will fail, but the outer call won't revert
        vm.prank(user);
        c.Collect(collectAmt);

        // After the call, MinSum must still equal the value set via SetMinSum
        assertTrue(c.MinSum() == minSum);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

