import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 collectAmount, uint256 newMinSum) public {
        // Admissible: initialize the contract once
        c.Initialized();

        // Set an initial MinSum to a small value to allow collection
        c.SetMinSum(0);

        // Use a helper that re-enters during Collect to call SetMinSum with a new value
        ReentrantAttacker attacker = new ReentrantAttacker(c, newMinSum);
        vm.deal(address(attacker), collectAmount + 1 ether);

        // Ensure unlockTime allows collect: Put funds with a lockTime that has already passed
        vm.warp(1000);
        vm.startPrank(address(attacker));
        c.Put{value: collectAmount + 1 ether}(lockTime);
        vm.stopPrank();

        // Warp past unlockTime so Collect succeeds
        uint unlock = c.Acc(address(attacker)).unlockTime;
        vm.warp(unlock + 1);

        // Record MinSum before Collect
        uint minSumBefore = c.MinSum();

        vm.startPrank(address(attacker));
        // Attacker's fallback will call c.SetMinSum(newMinSum) reentrantly
        attacker.attack(collectAmount);
        vm.stopPrank();

        uint minSumAfter = c.MinSum();

        // Property: MinSum cannot change after initialization. Initialization is done in setUp, so MinSum must be invariant.
        // The reference C satisfies minSumBefore == minSumAfter for all inputs. The buggy version sets MinSum to newMinSum reentrantly.
        assertTrue(minSumBefore == minSumAfter);
    }
}

