import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint128 amt) public {
        vm.assume(_val > 0);
        vm.assume(_lockTime > 0);
        vm.assume(amt > 0);

        // Initialized is required to set MinSum and use Put
        c.Initialized();
        c.SetMinSum(_val);

        // Fund a user and call Put, which acquires the nonReentrant_ lock
        address user = address(0x1234);
        vm.deal(user, amt);
        vm.startPrank(user);
        // Use Put which is nonReentrant_, acquiring the lock
        // Since Put is nonReentrant_ and calls AddMessage on Log,
        // any reentrant call from within Put would be blocked.
        // But here we call Put normally.
        c.Put{value: amt}(_lockTime);
        vm.stopPrank();

        // Now attempt to call SetLogFile while inside a nonReentrant_ context.
        // We create a malicious contract that re-enters SetLogFile during a nonReentrant_ call.
        // Put calls Log.AddMessage; if Log is a malicious contract, it can re-enter.
        MaliciousLog mal = new MaliciousLog();
        // Set the malicious log as the Log address
        c.SetLogFile(address(mal));

        address user2 = address(0x5678);
        vm.deal(user2, amt);

        // The property: SetLogFile cannot be called while the contract is locked (i.e., during a nonReentrant_ function).
        // The correct C should revert any attempt to call SetLogFile during a nonReentrant_ lock.
        // The buggy M allows SetLogFile to be called even when locked.
        // We test this by making Put call AddMessage on a malicious Log that re-enters SetLogFile.
        // In C, this should revert; in M, it proceeds.
        bool ok = true;
        vm.prank(user2);
        try c.Put{value: amt}(_lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        // The correct C reverts (ok == false) because re-entrant SetLogFile is blocked by nonReentrant_.
        // The buggy M does not revert (ok == true) because SetLogFile lacks the modifier and succeeds.
        assertTrue(!ok);
    }
}

contract MaliciousLog {
    // This contract acts as LogFile but re-enters SetLogFile when AddMessage is called.
    // Put calls Log.AddMessage, so during Put's execution, AddMessage can call back into SetLogFile.
    C target;
    function AddMessage(address, uint256, string memory) external {
        target.SetLogFile(address(this));
    }
}

